test("CAT-284: short pages caused by deleted rows do not end the export", () => {
  const gateway = new MemoryGateway({ invoices: [{id:"i-1",name:"A"},{id:"i-2",name:"B",deleted:true},{id:"i-3",name:"C"}] });
  assert.deepEqual(exportCatalog(gateway, "invoices", {pageSize:2}).entries.map(r=>r.id), ["i-1","i-3"]);
});
test("continues past a page that is entirely deleted", () => {
  const gateway = new MemoryGateway({ invoices: [{id:"1",name:"A",deleted:true},{id:"2",name:"B",deleted:true},{id:"3",name:"C"}] });
  assert.deepEqual(exportCatalog(gateway, "invoices", {pageSize:2}).entries.map(r=>r.id), ["3"]);
});
